import { useQuery } from '@tanstack/react-query';
import { queryKeys } from '../../constants/queryKeys';
import ApiService from '../../services/api';
import type { PeerBenchmarkData } from '../../components/dashboard/IndustryPeerBenchmarkDashboard';

export function useIndustryPeerBenchmarkQuery(enabled = true) {
  return useQuery({
    queryKey: queryKeys.platform.peerBenchmark,
    queryFn: async () => {
      const response = await ApiService.getIndustryPeerBenchmark();
      return ((response as { data?: PeerBenchmarkData })?.data || null) as PeerBenchmarkData | null;
    },
    enabled,
    staleTime: 5 * 60 * 1000,
  });
}

export function useSupplierCarbonScoresQuery(limit = 25, enabled = true) {
  return useQuery({
    queryKey: [...queryKeys.platform.supplierScores, limit],
    queryFn: async () => {
      const response = await ApiService.getSupplierCarbonScores(limit);
      return (response as { data?: unknown })?.data || null;
    },
    enabled,
    staleTime: 5 * 60 * 1000,
  });
}
