import React from 'react';
import { Alert, AlertTitle, Box, Button, List, ListItem, ListItemText, Stack } from '@mui/material';

export type PipelinePartialFailure = {
  type?: string;
  id?: string;
  message?: string;
};

type Props = {
  failures?: PipelinePartialFailure[];
  onRetry?: () => void;
};

const PipelinePartialFailureBanner: React.FC<Props> = ({ failures = [], onRetry }) => {
  if (!failures.length) {
    return null;
  }

  return (
    <Alert severity="warning" sx={{ mb: 2 }}>
      <AlertTitle>Some report steps did not complete</AlertTitle>
      <Box component="p" sx={{ m: 0, mb: 1 }}>
        Your bundle may be incomplete. Review the items below and retry generation after fixing data gaps.
      </Box>
      <List dense disablePadding>
        {failures.slice(0, 8).map((failure, index) => (
          <ListItem key={`${failure.id || failure.type}-${index}`} disableGutters>
            <ListItemText
              primary={failure.id || failure.type || 'Unknown step'}
              secondary={failure.message || 'Step failed without details'}
            />
          </ListItem>
        ))}
      </List>
      {onRetry ? (
        <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
          <Button size="small" variant="outlined" onClick={onRetry}>
            Retry generation
          </Button>
        </Stack>
      ) : null}
    </Alert>
  );
};

export default PipelinePartialFailureBanner;
